#nullable enable // autogenerated

using MVZ2.GameContent.Damages;
using MVZ2.Vanilla.Armors;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Carts;
using MVZ2.Vanilla.Effects;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Shells;
using MVZ2Logic;
using MVZ2Logic.Callbacks;
using MVZ2Logic.Entities;
using MVZ2Logic.Modding;
using PVZEngine;
using PVZEngine.Callbacks;
using PVZEngine.Damages;
using PVZEngine.Entities;
using PVZEngine.Level;
using UnityEngine;

namespace MVZ2.GameContent.GlobalCallbacks
{
    [ModGlobalCallbacks]
    public class EntityGlobalCallbacks : VanillaGlobalCallbacks
    {
        public override void Apply(Mod mod)
        {
            mod.AddTrigger(LevelCallbacks.POST_ENTITY_CONTACT_GROUND, PostContactGroundCallback);
            mod.AddTrigger(VanillaLevelCallbacks.PRE_ENTITY_TAKE_DAMAGE, PreEntityTakeDamageCallback);
            mod.AddTrigger(VanillaLevelCallbacks.POST_ENTITY_TAKE_DAMAGE, PostDamageCallback);
            mod.AddTrigger(VanillaLevelCallbacks.APPLY_DAMAGE_SPECIAL_EFFECTS, ApplyDamageEffectsCallback);
            mod.AddTrigger(LevelCallbacks.POST_ENTITY_UPDATE, HealParticlesUpdateCallback);
            mod.AddTrigger(LevelCallbacks.POST_ENTITY_DEATH, PostEntityDeathCallback);
            mod.AddTriggerFiltered(LevelCallbacks.POST_ENTITY_DEATH, PostEnemyDeathCallback, filter: EntityTypes.ENEMY);
            mod.AddTrigger(LevelCallbacks.POST_DESTROY_ARMOR, PostArmorDestroyCallback);
        }
        private void PostContactGroundCallback(LevelCallbacks.PostEntityContactGroundParams param, CallbackResultVoid result)
        {
            var entity = param.entity;
            var velocity = param.velocity;
            if (!entity.IsVulnerableEntity())
                return;
            if (!entity.IsAboveLand())
                return;
            if (velocity.y >= 0)
                return;

            var damageThresold = -entity.GetFallResistance();
            if (velocity.y > damageThresold)
                return;
            var fallDamage = 2.5f * Mathf.Pow(velocity.y - damageThresold, 2);
            if (fallDamage > 0)
            {
                var effects = new DamageEffectList(VanillaDamageEffects.IGNORE_ARMOR, VanillaDamageEffects.FALL_DAMAGE);
                entity.TakeDamageNoSource(fallDamage, effects);
            }
        }
        private void ApplyDamageEffectsCallback(VanillaLevelCallbacks.PostTakeDamageParams param, CallbackResultVoid callbackResult)
        {
            var output = param.output;
            var entity = output.Entity;
            if (entity.Type != EntityTypes.ENEMY)
                return;
            var bodyResult = output.BodyResult;
            var armorResult = output.ArmorResult;
            ILevelSourceReference? slowSource = null;
            ILevelSourceReference? unfreezeSource = null;
            bool slow = false;
            bool unfreeze = false;
            if (bodyResult != null)
            {
                if (bodyResult.HasEffect(VanillaDamageEffects.SLOW))
                {
                    slow = true;
                    slowSource = bodyResult.Source;
                }
                if (bodyResult.HasEffect(VanillaDamageEffects.FIRE))
                {
                    unfreeze = true;
                    unfreezeSource = bodyResult.Source;
                }
            }
            if (armorResult != null)
            {
                if (armorResult.HasEffect(VanillaDamageEffects.SLOW))
                {
                    slow = true;
                    slowSource = armorResult.Source;
                }
                if (armorResult.HasEffect(VanillaDamageEffects.FIRE))
                {
                    unfreeze = true;
                    unfreezeSource = armorResult.Source;
                }
            }
            if (unfreeze)
            {
                entity.Unfreeze(unfreezeSource);
            }
            else if (slow)
            {
                entity.InflictSlow(300, slowSource);
            }
        }
        private void PreEntityTakeDamageCallback(VanillaLevelCallbacks.PreTakeDamageParams args, CallbackResult<bool> result)
        {
            var damageInfo = args.input;
            var entity = damageInfo.Entity;
            if (entity.ImmuneFire() && damageInfo.Effects.HasEffect(VanillaDamageEffects.FIRE))
            {
                damageInfo.Multiply(0);
            }
        }
        private void PostDamageCallback(VanillaLevelCallbacks.PostTakeDamageParams param, CallbackResultVoid callbackResult)
        {
            var output = param.output;
            var entity = output.Entity;
            var bodyResult = output.BodyResult;
            if (bodyResult != null)
            {
                var shellDefinition = bodyResult.ShellDefinition;
                if (bodyResult.Effects.HasEffect(VanillaDamageEffects.SLICE) && shellDefinition != null && shellDefinition.IsSliceCritical())
                {
                    entity.EmitBlood();
                }
            }
            output.PlayHitSound();
        }
        private void PostEntityDeathCallback(LevelCallbacks.EntityDeathParams param, CallbackResultVoid result)
        {
            var entity = param.entity;
            var info = param.deathInfo;
            if (entity.ShouldTriggerDeathEffects(info))
            {
                using var behavioursItem = entity.Definition.GetBehavioursDisposeable<IDeathEffectsBehaviour>();
                foreach (var behaviour in behavioursItem.Value)
                {
                    behaviour.DeathEffects(entity, info);
                }
                entity.Level.Triggers.RunCallbackFiltered(LogicLevelCallbacks.ENTITY_DEATH_EFFECTS, param, entity.Type);
            }
        }
        private void PostEnemyDeathCallback(LevelCallbacks.EntityDeathParams param, CallbackResultVoid result)
        {
            var entity = param.entity;
            var info = param.deathInfo;
            if (info.HasEffect(VanillaDamageEffects.NO_NEUTRALIZE) || entity.NoNeutralizedOnDeath())
                return;
            entity.Neutralize();
        }
        private void HealParticlesUpdateCallback(EntityCallbackParams param, CallbackResultVoid result)
        {
            var entity = param.entity;
            entity.UpdateHealParticles();
        }
        private void PostArmorDestroyCallback(LevelCallbacks.PostArmorDestroyParams param, CallbackResultVoid result)
        {
            var armor = param.armor;
            var entity = param.entity;
            var deathSound = armor.GetDeathSound();
            if (!NamespaceID.IsValid(deathSound))
                return;
            entity.PlaySound(deathSound);
        }
    }
}
